<?php declare(strict_types=1); ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configurações — ZystemWorkSpace</title><style>:root{font:15px system-ui;color:#e8eef7;background:#080d14}body{margin:0;padding:28px;max-width:1100px}main{max-width:1100px;margin:auto}.toplinks{margin-bottom:14px}.toplinks a{color:#bcd8ff}.hero,.panel{background:linear-gradient(145deg,#101a28,#0d1622);border:1px solid #263b56;border-radius:16px;padding:20px;margin-bottom:14px;box-shadow:0 16px 40px #0002}.hero{display:flex;justify-content:space-between;gap:18px}.hero h1{margin:0 0 7px}.muted{color:#91a5bd;line-height:1.5}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}label{display:block;color:#b9cbe0;font-size:13px}input,select,button{font:inherit;width:100%;box-sizing:border-box;padding:10px;margin:5px 0 10px;border-radius:8px;border:1px solid #385474;background:#0b1420;color:#e8eef7}button{width:auto;background:#193b5d;cursor:pointer;margin-right:6px}button:hover{background:#25527c}.status{min-height:24px;color:#9fe0b0}.error{color:#ff9d9d}.model-list{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.model{padding:6px 9px;border-radius:99px;background:#172a42;color:#c6ddf7;font-size:12px}.card{border:1px solid #263b56;border-radius:10px;padding:12px;margin-top:9px}.on{color:#8ee0ad}.off{color:#ffd786}pre{white-space:pre-wrap;background:#0b1420;padding:12px;border-radius:8px;overflow:auto}@media(max-width:700px){body{padding:18px}.hero{display:block}}
</style></head><body><?php require __DIR__ . '/menu.php'; ?><main><div class="toplinks"><a href="index.php">Chat</a> · <a href="files.php">Arquivos</a> · <a href="skills.php">Habilidades</a> · <a href="plugins.php">Plugins</a></div><section class="hero"><div><h1>Configurações</h1><p class="muted">Mantenha seu provedor atual e teste o LM Studio quando quiser. A troca de servidor é opcional e não remove seus modelos.</p></div><div id="currentBadge" class="model">Verificando…</div></section><section class="panel"><h2>Provedor atualmente configurado</h2><div id="info">Carregando...</div><button id="testCurrent">Validar conexão atual</button><pre id="currentResult"></pre></section><section class="panel"><h2>LM Studio — conexão opcional</h2><p class="muted">O padrão costuma ser <code>http://127.0.0.1:1234/v1</code>. O teste apenas consulta <code>/models</code>; não altera sua configuração atual.</p><form id="lmForm"><div class="grid"><label>URL base<input name="url" value="http://127.0.0.1:1234/v1" required></label><label>API key (opcional)<input name="api_key" placeholder="lm-studio" autocomplete="off"></label></div><button>Testar LM Studio</button></form><div id="lmStatus" class="status"></div><div id="models" class="model-list"></div><p class="muted">Para usar o LM Studio no launcher, configure <code>MANUZ_LLM_URL=http://127.0.0.1:1234/v1</code>. O provedor atual continua disponível quando essa variável não estiver definida.</p></section><section class="panel"><h2>APIs e serviços externos</h2><p class="muted">Cadastre integrações sem colocar chaves diretamente no código.</p><form id="form"><input type="hidden" name="id"><div class="grid"><label>Nome<input name="name" required placeholder="GitHub API"></label><label>Tipo<select name="kind"><option value="rest">REST</option><option value="graphql">GraphQL</option><option value="ftp">FTP</option><option value="mysql">MySQL</option><option value="postgresql">PostgreSQL</option><option value="web_search">Busca web autenticada</option><option value="automation">Automação</option></select></label><label>URL base<input name="base_url" placeholder="https://api.exemplo.com"></label><label>Autenticação<select name="auth_type"><option value="none">Nenhuma</option><option value="bearer_env">Bearer por variável</option><option value="header_env">Header por variável</option><option value="basic_env">Basic por variável</option><option value="ssh_key_file">Arquivo de chave SSH</option></select></label><label>Variável da credencial<input name="credential_ref" pattern="[A-Z][A-Z0-9_]{2,119}" placeholder="GITHUB_TOKEN"></label><label>Endpoint de teste<input name="test_endpoint" placeholder="/user ou /health"></label><label>Nome do header<input name="header_name" placeholder="X-API-Key"></label><label>Porta<input name="port" type="number" placeholder="21"></label><label>Pasta inicial<input name="folder" placeholder="/public_html"></label><label>Banco<input name="database" placeholder="nome_do_banco"></label><label>Modo<select name="read_only"><option value="1">Somente leitura</option><option value="0">Leitura e escrita</option></select></label><label>Ativa<input name="enabled" type="checkbox" value="1"></label></div><button>Salvar integração</button><button type="button" id="clear">Limpar</button></form><div id="msg" class="status"></div><div id="items">Carregando integrações...</div></section></main><script>const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(url,opt){const r=await fetch(url,opt),d=await r.json();if(!d.ok)throw Error(d.error||'Falha');return d}async function showCurrent(){try{const d=await api('../api/settings.php?action=status');$('#info').innerHTML=`<div class="card"><b>Provedor:</b> ${esc(d.llm.provider)}<br><b>URL:</b> ${esc(d.llm.base_url)}<br><b>Modelo fixado:</b> ${esc(d.llm.model||'automático')}</div>`;$('#currentBadge').textContent=d.llm.provider+' · '+(d.llm.model||'automático')}catch(e){$('#info').textContent=e.message}}async function testCurrent(){const r=$('#currentResult');r.textContent='Consultando /models…';try{const d=await api('../api/settings.php?action=test_llm');r.textContent=JSON.stringify(d,null,2)}catch(e){r.textContent='Falha: '+e.message}}$('#testCurrent').onclick=testCurrent;$('#lmForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),st=$('#lmStatus'),box=$('#models');st.className='status';st.textContent='Testando LM Studio…';box.innerHTML='';try{const d=await api('../api/settings.php?action=probe_llm&url='+encodeURIComponent(f.get('url'))+'&api_key='+encodeURIComponent(f.get('api_key')||''));st.textContent=`Conectado. ${d.models.length} modelo(s). Ativo: ${d.active_model||'nenhum fixado'}`;box.innerHTML=d.models.map(x=>`<span class="model">${esc(x)}</span>`).join('')||'<span class="muted">Nenhum modelo publicado.</span>'}catch(x){st.textContent=x.message;st.className='status error'}};const form=$('#form'),msg=$('#msg'),items=$('#items');async function load(){const d=await api('../api/integrations.php?action=list');items.innerHTML=d.items.map(x=>`<div class="card"><b>${esc(x.name)}</b> — ${esc(x.kind)} — <span class="${x.enabled?'on':'off'}">${x.enabled?'ativa':'desativada'}</span><br><small>${esc(x.base_url||'sem URL')} · credencial: ${esc(x.credential_ref||'nenhuma')}</small></div>`).join('')||'<p class="muted">Nenhuma integração cadastrada.</p>'}form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),extra={};for(const n of ['header_name','port','folder','database','read_only'])if(f.get(n)!==null)extra[n]=f.get(n);try{await api('../api/integrations.php?action=save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:Number(f.get('id')||0),name:f.get('name'),kind:f.get('kind'),base_url:f.get('base_url'),auth_type:f.get('auth_type'),credential_ref:f.get('credential_ref'),test_endpoint:f.get('test_endpoint'),enabled:f.get('enabled')==='1',config_json:extra})});msg.textContent='Integração salva.';form.reset();load()}catch(x){msg.textContent=x.message;msg.className='status error'}};$('#clear').onclick=()=>form.reset();showCurrent();load().catch(e=>items.textContent=e.message)</script></body></html>
